"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["68331"],{51076(e){e.exports=JSON.parse('{"id":"FIN-659","slug":"dividend-policy","term":"Dividend Policy","also_known_as":[],"difficulty":"Intermediate","definition":"Dividend policy is a company\'s approach to deciding how much of its profits to pay out to shareholders as dividends and how much to retain for reinvestment.","explanation":["Every profitable company must decide what to do with its earnings. Its dividend policy guides those decisions over time.","Companies follow different approaches. A stable dividend policy aims for steady, predictable dividends that rise gradually, even if profits fluctuate. A target payout policy aims to pay out a set percentage of earnings, so dividends rise and fall with profits. A residual policy pays dividends only from profits left over after funding all attractive investment opportunities. Some companies pay no regular dividends at all, preferring to reinvest or return cash through share buybacks.","For example, a mature utility might aim to raise its dividend by about 3% each year, while a fast-growing technology company might pay nothing and reinvest all its profits.","Dividend policy sends signals to investors. Many companies are reluctant to cut dividends, because a cut is often seen as a sign of financial trouble and can cause the share price to fall. An unexpected increase may signal management\'s confidence in the future.","The best policy depends on the company\'s growth opportunities, cash flow stability, debt levels, shareholder preferences and tax considerations."],"note":"","total":1500,"prev":{"slug":"dividend-payout-ratio","term":"Dividend Payout Ratio"},"next":{"slug":"dividend-reinvestment-plan","term":"Dividend Reinvestment Plan (DRIP)"}}')}}]);